const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=1)=>Number.isFinite(n)?n.toFixed(d):'—',meter=n=>fmt(n*.3048),clock=n=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
const state={catalog:[],data:null,shot:null,player:null,scope:'top',search:'',outcome:'all',connected:false,busy:false,results:new Map(),view:'court',videoURL:null,videoGame:null,alignment:new Map()};
let loadVersion=0,toastTimer;
const key=()=>`${state.data?.game.id}/${state.shot}/${state.player}`;
const shot=()=>state.data?.shots.find(s=>s.id===state.shot),candidate=()=>shot()?.analysis.candidates.find(c=>c.playerId===state.player);
function toast(msg){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function status(msg,progress=0,error=false){$('status').hidden=!msg;$('status-text').textContent=msg;$('progress').value=progress;$('status').classList.toggle('error',error);}
async function api(path,options={}){const res=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json','X-Team-Key':sessionStorage.getItem('hi-team-key')||'',...options.headers},signal:options.signal||AbortSignal.timeout(45000)});let body;try{body=await res.json();}catch{throw new Error('云端暂未返回有效结果。');}if(!res.ok){if(res.status===401){setConnected(false);$('login-dialog').showModal();}throw new Error(body.error||`请求失败（${res.status}）`);}return body;}
function setConnected(ok){state.connected=ok;$('connect').classList.toggle('connected',ok);$('connection-label').textContent=ok?'团队云端已连接':'连接云端';}
async function connect(){try{await api('/session');setConnected(true);return true;}catch{return false;}}
function visibleShots(){let arr=state.data?.shots||[];if(state.scope==='top')arr=arr.filter(s=>s.analysis.eligible);if(state.scope==='screens')arr=arr.filter(s=>(s.context?.events.off_ball_screens||[]).length);if(state.outcome!=='all')arr=arr.filter(s=>s.outcome===state.outcome);if(state.search)arr=arr.filter(s=>[s.shooterName,s.team,...s.analysis.candidates.map(c=>c.name)].join(' ').toLowerCase().includes(state.search));arr=[...arr].sort((a,b)=>(b.analysis.score??-1)-(a.analysis.score??-1));return state.scope==='top'?arr.slice(0,10):arr;}
async function loadGame(id){const version=++loadVersion;try{const entry=state.catalog.find(x=>x.id===id);if(!entry)return;const response=await fetch(entry.file);if(!response.ok)throw new Error('比赛文件读取失败');const data=await response.json();if(version!==loadVersion)return;state.data=data;state.shot=null;state.player=null;$('game-select').value=id;render();}catch(e){status(e.message,0,true);}}
function render(){if(!state.data)return;const list=visibleShots();if(!list.some(s=>s.id===state.shot)){state.shot=list[0]?.id||null;state.player=null;}$('shot-count').textContent=`${state.data.shots.length} 次出手`;$('event-count').textContent=list.length;$('event-list').innerHTML=list.length?list.map((s,i)=>`<button class="event-card ${s.id===state.shot?'selected':''}" data-shot="${esc(s.id)}"><div class="event-card-head"><span>${String(i+1).padStart(2,'0')}　Q${s.period} · ${clock(s.gameClock)}</span><span>${s.outcome==='made'?'命中':s.outcome==='missed'?'未中':'未知'}</span></div><h3>${esc(s.shooterName)} 的出手</h3><div class="event-card-bottom"><span>${esc(s.analysis.candidates[0]?.name||'点位不足')}</span><b>${fmt(s.analysis.score,0)}</b></div>${s.context?.events.off_ball_screens.length?'<span class="shot-tag">有无球掩护证据</span>':''}</button>`).join(''):'<div class="empty-state"><h3>没有匹配回合</h3><p>调整筛选或清空搜索。</p></div>';for(const [id,scope] of [['top-scope','top'],['all-scope','all'],['screen-scope','screens']])$(id).classList.toggle('active',state.scope===scope);renderDetail();}
function renderDetail(){const s=shot();if(!s){$('play-title').textContent='暂无匹配回合';$('court').innerHTML='';$('impact-content').innerHTML='<div class="impact-empty">暂无评分</div>';$('impact-details').innerHTML='';$('candidates').innerHTML='';$('action-list').innerHTML='';$('narrative').textContent='调整筛选后继续。';$('insight-meta').textContent='';$('ai-evidence').textContent='';for(const id of ['shot-quality','defender-distance','shot-outcome','play-clock'])$(id).textContent='—';$('analyze-btn').disabled=true;$('export-json').disabled=true;return;}
if(!s.analysis.candidates.some(c=>c.playerId===state.player))state.player=s.analysis.candidates[0]?.playerId||null;const c=candidate();$('play-title').textContent=`${s.shooterName} · ${s.team}`;$('play-clock').textContent=`第 ${s.period} 节　${clock(s.gameClock)}`;$('shot-quality').textContent=fmt(s.shotQuality);$('defender-distance').textContent=Number.isFinite(s.defenderDistance)?meter(s.defenderDistance):'—';$('shot-outcome').textContent=s.outcome==='made'?`命中 ${s.points||2} 分`:s.outcome==='missed'?'未命中':'未知';$('candidate-count').textContent=`${s.analysis.candidates.length} 人`;$('analyze-btn').disabled=!c||state.busy||state.data.game.id==='imported';$('export-json').disabled=false;
$('impact-content').innerHTML=c?`<div class="score-block"><span class="score-label">HIDDEN IMPACT INDEX</span><div class="score-value"><strong>${fmt(c.score,0)}</strong><span>/ 100</span></div><h3 class="actor-name">${esc(c.name)}</h3><p class="actor-role">#${esc(c.jersey)} · 无球空间贡献候选</p><span class="confidence ${c.keyPointsReliable?'':'low'}">${c.keyPointsReliable?'关键点位较可靠':'点位需复核'}</span></div>`:'<div class="impact-empty"><div class="score-placeholder">—</div>数据不足，暂不评分</div>';
$('impact-details').innerHTML=c?`<div class="contribution-bars">${c.components.map(x=>`<div class="bar-row"><div class="bar-label"><span>${esc(x.label)}</span><b>${fmt(x.points)} / ${x.weight}</b></div><div class="bar-track"><i style="width:${x.value}%"></i></div></div>`).join('')}<div class="evidence-values"><div><span>与出手者间距</span><b>${meter(c.shooterSpacingFt)} m</b></div><div><span>最近防守距离</span><b>${meter(c.nearestDefenderFt)} m</b></div></div></div>`:'';
$('candidates').innerHTML=s.analysis.candidates.map(p=>`<button class="candidate-row ${p.playerId===state.player?'active':''}" data-player="${esc(p.playerId)}"><i>${esc(p.jersey)}</i><span>${esc(p.name)}</span><b>${fmt(p.score,0)}</b></button>`).join('');renderCourt();renderActions();renderNarrative();renderVideo();$('raw-evidence').textContent=JSON.stringify({shot:s,candidate:c},null,2);history.replaceState(null,'',`#${encodeURIComponent(state.data.game.id)}/${encodeURIComponent(s.id)}/${encodeURIComponent(state.player||'')}`);}
function courtSVG(){const s=shot(),c=candidate();if(!s)return '';const full=(s.players||[]).some(p=>p.x>2);const scale=full?7.6:10.4;const pos=p=>full?{x:450+p.x*scale,y:280-p.y*scale}:{x:450+p.y*scale,y:38+(p.x+46)*scale};const point=(x,y)=>{let p=pos({x,y});return `${p.x},${p.y}`;};const lines=full?`<rect x="100" y="90" width="700" height="380"/><line x1="450" y1="90" x2="450" y2="470"/><circle cx="450" cy="280" r="46"/>${[1,-1].map(sign=>`<circle cx="${450+sign*41.75*scale}" cy="280" r="7"/><rect x="${sign===1?650:100}" y="210" width="150" height="140"/>`).join('')}`:`<rect x="194" y="38" width="512" height="478"/><rect x="367" y="38" width="166" height="200"/><path d="M367 238a83 83 0 0 0 166 0"/><path d="M367 238a83 83 0 0 1 166 0" stroke-dasharray="5 6"/><path d="M221 38v117a242 242 0 0 0 458 0V38"/><circle cx="450" cy="82" r="9"/><path d="M425 70h50" stroke-width="3"/><path d="M410 82a40 40 0 0 0 80 0"/><path d="M390 516a60 60 0 0 1 120 0"/>`;
let html=`<rect width="900" height="560" fill="#193a35"/><g stroke="#719487" stroke-width="1.2" fill="none" opacity=".7">${lines}</g><text x="450" y="350" text-anchor="middle" font-family="Arial" font-size="26" letter-spacing="8" fill="#2a4a40">HIDDEN IMPACT</text>`;
const byId=Object.fromEntries((s.players||[]).map(p=>[p.id,p])),cp=byId[c?.playerId],sp=byId[s.shooterId];if(cp&&sp){const a=pos(cp),b=pos(sp),dp=byId[c.links[0]?.defenderId];html+=`<circle cx="${a.x}" cy="${a.y}" r="32" fill="#d6f59b" opacity=".09"/><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#c5dba4" stroke-width="1.3" stroke-dasharray="5 6"/><text x="${(a.x+b.x)/2+6}" y="${(a.y+b.y)/2-8}" fill="#b0c695" font-family="Arial" font-size="11">${meter(c.shooterSpacingFt)} m</text>`;if(dp){const d=pos(dp);html+=`<line x1="${a.x}" y1="${a.y}" x2="${d.x}" y2="${d.y}" stroke="#d0e6ad" opacity=".7" stroke-width="2"/>`;}}
for(const p of s.players||[]){const q=pos(p),selected=p.id===state.player,shooter=p.id===s.shooterId,off=p.teamId===s.offenseId;const fill=shooter?'#e3ad86':selected?'#d6f59b':off?'#779d97':'#19332f';html+=`<g class="court-player" data-player="${esc(p.id)}" ${off?'tabindex="0" role="button"':''} aria-label="${esc(p.name)} #${esc(p.jersey)}"><circle cx="${q.x}" cy="${q.y}" r="${selected||shooter?15:12}" fill="${fill}" stroke="${off?fill:'#acc1b5'}" stroke-width="1.5" ${!p.detected?'stroke-dasharray="3 3"':''}/><text x="${q.x}" y="${q.y+4}" text-anchor="middle" fill="${off?'#153326':'#becfc8'}" font-family="Arial" font-size="11" font-weight="600">${esc(p.jersey)}</text></g>`;if(selected||shooter){let name=p.name.split(' ').slice(-1)[0];html+=`<text x="${Math.max(80,Math.min(820,q.x))}" y="${q.y>85?q.y-23:q.y+31}" text-anchor="middle" font-family="Arial" font-size="11" fill="${shooter?'#e8bca1':'#d6e9b6'}">${esc(name)}</text>`;}}
if(!s.players?.length)html+='<text x="450" y="280" text-anchor="middle" fill="#b5c4b9" font-size="20">缺少点位，暂不绘制球员</text>';return html;}
function renderCourt(){$('court').innerHTML=courtSVG();}
function renderActions(){const s=shot(),c=candidate();const name=id=>s.players.find(p=>p.id===String(id))?.name||`球员 ${id}`;const screens=s.context?.events.off_ball_screens||[],picks=s.context?.events.picks||[];const actions=[...screens.map(r=>({...r,kind:'无球掩护'})),...picks.map(r=>({...r,kind:'持球掩护'}))].sort((a,b)=>(b.screenerId===Number(c?.playerId))-(a.screenerId===Number(c?.playerId))).slice(0,3);$('action-count').textContent=`${screens.length} 次无球掩护 · ${picks.length} 次持球掩护`;$('action-list').innerHTML=actions.length?actions.map(a=>`<div class="action-item ${a.screenerId===Number(c?.playerId)?'linked':''}"><span>出手前 ${fmt((s.frame-a.frame)/25)} 秒 · ${a.kind}</span><h3>${esc(name(a.screenerId))}</h3><p>接应：${esc(name(a.cutterId??a.ballhandlerId))}<br>覆盖：${esc(a.cutterDefType||a.bhrDefType||'未知')} / ${esc(a.screenerDefType||a.scrDefType||'未知')}</p></div>`).join(''):'<div class="inline-empty">这一回合没有已记录的掩护事件；当前只分析出手站位。</div>';}
function renderNarrative(){const s=shot(),c=candidate(),result=state.results.get(key());$('insight-title').textContent=result?.title||'这个机会，如何被创造？';$('narrative').textContent=result?.summary||(c?`${s.shooterName} 出手时，${c.name} 与他的间距为 ${meter(c.shooterSpacingFt)} 米，最近防守人与 ${c.name} 相距 ${meter(c.nearestDefenderFt)} 米。点击 AI 解读，结合本回合的掩护和防守数据解释这组空间关系。`:s.analysis.summary);$('insight-meta').innerHTML=result?`<span>✦ Qwen3-VL · 真实云端生成</span><span>${esc(result.visualInput==='rendered-shot-diagram'?'战术图＋结构化数据':'视频关键帧＋同回合数据')}</span><span>${result.usage?.totalTokens||'—'} tokens</span>`:'<span>当前为数据摘要</span><span>AI 将结合真实事件生成解说</span>';$('ai-evidence').innerHTML=result?`<details><summary>查看 ${result.evidence?.length||0} 条 AI 证据引用</summary><ul>${(result.evidence||[]).map(e=>`<li>${esc(e.claim)}<code>${esc(e.sourceIds.join(' · '))}</code></li>`).join('')}</ul><p style="font-size:10px">${esc(result.caveat)}</p></details>`:'';}
function renderVideo(){const isVideo=state.view==='video';$('tactics-stage').hidden=isVideo;$('video-stage').hidden=!isVideo;$('video-notice').hidden=!isVideo;$('court-tab').classList.toggle('active',!isVideo);$('video-tab').classList.toggle('active',isVideo);if(!isVideo){$('matched-video').pause();return;}
const local=state.videoURL&&state.videoGame===state.data.game.id;$('matched-video').hidden=!local;$('reference-video').hidden=local||state.data.game.id!=='114243';$('video-empty').hidden=local||state.data.game.id==='114243';if(local){$('video-notice').textContent='本地同场录像 · 双击视频下方“关联本地录像”可设置当前回合时间并分析视频。';}else if(state.data.game.id==='114243'){if(!$('reference-video').src)$('reference-video').src='https://player.vimeo.com/video/1126497253?dnt=1';$('video-notice').innerHTML='ACB 官方同场集锦 · 尚未逐回合对齐，不随左侧回合自动跳转。<a href="https://vimeo.com/1126497253" target="_blank" rel="noreferrer">打开原视频 ↗</a>';}else{$('video-notice').textContent='当前数据包不含录像。可关联你持有的同场比赛文件。';}}
function choosePlayer(id){if(!shot()?.analysis.candidates.some(c=>c.playerId===id))return;state.player=id;renderDetail();}
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
async function diagramImage(){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="560" viewBox="0 0 900 560">${courtSVG()}</svg>`,url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const canvas=document.createElement('canvas');canvas.width=900;canvas.height=560;canvas.getContext('2d').drawImage(image,0,0);return canvas.toDataURL('image/jpeg',.8).split(',')[1];}finally{URL.revokeObjectURL(url);}}
async function runAnalysis(body,selectedKey){state.busy=true;$('analyze-btn').disabled=true;status('正在提交到 AgentCore…',15);try{const request=await api('/jobs',{method:'POST',body:JSON.stringify(body)});localStorage.setItem('hi-pending-job',JSON.stringify({job:request.job,key:selectedKey}));await pollJob(request.job,selectedKey);}catch(e){status(e.message,0,true);}finally{state.busy=false;renderDetail();}}
async function pollJob(job,selectedKey){const started=Date.now();while(Date.now()-started<660000){const data=await api('/jobs/'+job);if(data.status==='completed'){state.results.set(selectedKey,data.result);try{localStorage.setItem('hi-results',JSON.stringify([...state.results.entries()].slice(-40)));}catch{}localStorage.removeItem('hi-pending-job');status('分析完成 · 已返回带证据来源的 AI 解读',100);if(key()===selectedKey)renderNarrative();toast('AI 解读已生成');return;}if(data.status==='failed'){localStorage.removeItem('hi-pending-job');throw new Error(data.error||'分析失败，请重试。');}status(data.status==='running'?'Qwen3-VL 正在阅读图像和同回合数据…':'任务已进入云端队列…',Math.min(90,20+(Date.now()-started)/1000));await sleep(3000);}throw new Error('任务仍在执行，刷新后可以恢复结果查询。');}
async function analyzeCurrent(){if(state.busy||!candidate())return;if(!state.connected&&!(await connect()))return;const selectedKey=key();try{const image=await diagramImage();await runAnalysis({mode:'snapshot',gameId:state.data.game.id,shotId:state.shot,playerId:state.player,frames:[{time:0,image}]},selectedKey);}catch(e){status(e.message,0,true);}}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('game-select').onchange=e=>loadGame(e.target.value);$('search').oninput=e=>{state.search=e.target.value.toLowerCase().trim();render();};$('outcome').onchange=e=>{state.outcome=e.target.value;render();};for(const [id,scope] of [['top-scope','top'],['all-scope','all'],['screen-scope','screens']])$(id).onclick=()=>{state.scope=scope;render();};$('event-list').onclick=e=>{const b=e.target.closest('[data-shot]');if(b){state.shot=b.dataset.shot;state.player=null;render();}};$('candidates').onclick=e=>{const b=e.target.closest('[data-player]');if(b)choosePlayer(b.dataset.player);};$('court').onclick=e=>{const b=e.target.closest('[data-player]');if(b)choosePlayer(b.dataset.player);};$('court').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();const b=e.target.closest('[data-player]');if(b)choosePlayer(b.dataset.player);}};$('court-tab').onclick=()=>{state.view='court';renderVideo();};$('video-tab').onclick=()=>{state.view='video';renderVideo();};$('analyze-btn').onclick=analyzeCurrent;
for(const id of ['method-btn','source-btn'])$(id).onclick=()=>$('method-dialog').showModal();document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('connect').onclick=()=>$('login-dialog').showModal();$('login-form').onsubmit=async e=>{e.preventDefault();sessionStorage.setItem('hi-team-key',$('access-code').value.trim());if(await connect()){$('login-dialog').close();$('login-error').textContent='';toast('已连接赛事 AWS 工作区');}else{$('login-error').textContent='访问码无效，或云端暂时不可用。';}};
$('export-json').onclick=()=>{if(shot())download('hidden-impact-'+shot().id+'.json',{game:state.data.game,shot:shot(),candidate:candidate(),ai:state.results.get(key())||null});};$('speak-btn').onclick=()=>{if(!('speechSynthesis'in window))return toast('当前浏览器不支持朗读');if(speechSynthesis.speaking){speechSynthesis.cancel();return;}const u=new SpeechSynthesisUtterance($('narrative').textContent);u.lang='zh-CN';speechSynthesis.speak(u);};
$('import-btn').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>4*1024*1024)throw new Error('快照文件上限 4 MB');const data=await api('/analyze',{method:'POST',body:await f.text()});state.data=data;state.data.game.id='imported';state.shot=null;state.player=null;state.scope='all';state.search='';$('search').value='';render();status('导入快照已计算。云端 AI 当前支持内置、已核验的 SkillCorner 比赛。',100);}catch(e){toast(e.message);}e.target.value='';};
$('video-import').onclick=()=>{if(state.videoURL&&state.videoGame===state.data.game.id){$('video-dialog').showModal();return;}$('video-file').click();};$('video-file').onchange=e=>{const file=e.target.files[0];if(!file)return;if(state.videoURL)URL.revokeObjectURL(state.videoURL);state.videoURL=URL.createObjectURL(file);state.videoGame=state.data.game.id;$('matched-video').src=state.videoURL;state.view='video';renderVideo();$('video-dialog').showModal();e.target.value='';};$('video-align').onclick=()=>{const time=Number($('video-time').value);const v=$('matched-video');if(!Number.isFinite(v.duration)||time<0||time>v.duration)return toast('请填写录像范围内的出手时间');state.alignment.set(shot().id,time);v.currentTime=Math.max(0,time-8);$('video-dialog').close();toast('已保存当前回合的时间对应');};
$('analyze-video').onclick=async()=>{const v=$('matched-video'),time=Number($('video-time').value);if(!Number.isFinite(v.duration)||time<0||time>v.duration)return toast('请先填写正确的出手时间');if(!state.connected&&!(await connect()))return;const selectedKey=key();$('video-dialog').close();try{const frames=[],start=Math.max(0,time-10),end=Math.min(v.duration-.1,time+2);status('正在抽取同场视频关键帧…',5);v.pause();const canvas=document.createElement('canvas');canvas.width=960;canvas.height=Math.round(960*v.videoHeight/v.videoWidth);for(let i=0;i<16;i++){const t=start+(end-start)*i/15;await seek(v,t);canvas.getContext('2d').drawImage(v,0,0,canvas.width,canvas.height);frames.push({time:Number(t.toFixed(2)),image:canvas.toDataURL('image/jpeg',.75).split(',')[1]});}await runAnalysis({mode:'matched-video',gameId:state.data.game.id,shotId:state.shot,playerId:state.player,releaseTime:time,video:{id:state.data.game.id,title:state.data.game.home+' vs '+state.data.game.away,duration:v.duration},frames},selectedKey);}catch(e){status(e.message,0,true);}};
function seek(video,time){return new Promise((resolve,reject)=>{if(Math.abs(video.currentTime-time)<.01&&video.readyState>=2)return resolve();const timeout=setTimeout(()=>{video.removeEventListener('seeked',done);reject(new Error('视频抽帧超时'));},15000);function done(){clearTimeout(timeout);video.removeEventListener('seeked',done);resolve();}video.addEventListener('seeked',done);video.currentTime=time;});}
async function start(){try{try{state.results=new Map(JSON.parse(localStorage.getItem('hi-results')||'[]'));}catch{}const response=await fetch('data/catalog.json');state.catalog=await response.json();$('game-select').innerHTML=state.catalog.map(g=>`<option value="${esc(g.id)}">${esc(g.home)} vs ${esc(g.away)}</option>`).join('');const hash=location.hash.slice(1).split('/').map(decodeURIComponent);await loadGame(state.catalog.some(g=>g.id===hash[0])?hash[0]:state.catalog[0].id);if(hash[1]&&state.data.shots.some(s=>s.id===hash[1])){state.shot=hash[1];state.player=hash[2];if(!visibleShots().some(s=>s.id===state.shot))state.scope='all';render();}try{const demo=await fetch('data/ai-examples.json');if(demo.ok){for(const [k,v] of Object.entries(await demo.json()))if(!state.results.has(k))state.results.set(k,v);renderNarrative();}}catch{}try{await api('/session');setConnected(true);const pending=JSON.parse(localStorage.getItem('hi-pending-job')||'null');if(pending){state.busy=true;pollJob(pending.job,pending.key).catch(e=>status(e.message,0,true)).finally(()=>{state.busy=false;renderDetail();});}}catch{/* connection is optional for browsing */}}catch(e){status(e.message,0,true);}}
start();
